// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call adjustAdminAccess to set admin access for a specific address
        address admin = address(0x1234);
        c.adjustAdminAccess(admin, true);

        // Mint a token to an account to get non-zero balance
        // First create a game item so that mint can work
        // Since createGameItem and mint are admin-only, we can use the contract deployer (this) as admin
        vm.startPrank(address(this));
        c.createGameItem("item", "uri", true, true, 100, 1, 10);
        c.instantiateNeuronContract(address(0xdead)); // dummy address to avoid revert in mint when checking balance
        vm.stopPrank();

        // Mint token 0 to account 0x5678
        address recipient = address(0x5678);
        // We need the Neuron contract to have funds, but since we use a dummy, we'll directly check balanceOf
        // Instead, we observe that after createGameItem, _itemCount = 1, so tokenId 0 exists
        // The bug: balanceOf returns 0 always, while reference returns actual balance

        // After creation, balance of recipient for tokenId 0 should be 0
        uint256 balanceBefore = c.balanceOf(recipient, 0);
        // In reference, this returns 0; in bug, also 0. So we need to change state to make them differ.
        // The bug returns 0 regardless, so any mint will produce non-zero balance in reference but 0 in bug.
        // So we must mint to the recipient.
        // But mint requires Neuron balance etc. So instead we use safeTransferFrom to give tokens.
        // First we need to mint tokens to the contract deployer.
        vm.prank(address(this));
        c.mint(0, 100); // mint 100 tokens to this contract
        uint256 balanceThis = c.balanceOf(address(this), 0); // should be 100 in reference, 0 in bug

        // Now transfer from this contract to recipient
        vm.prank(address(this));
        c.safeTransferFrom(address(this), recipient, 0, 50, "");

        // Now check balance of recipient
        uint256 balanceRecipient = c.balanceOf(recipient, 0);
        // In reference: 50; in bug: 0
        assertTrue(balanceRecipient == 50, "balance should be 50");
    }
}

