pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Create a game item (tokenId 0) with finite supply, transferable, price 0, dailyAllowance 100
        c.createGameItem("Item", "ipfs://uri", true, true, 100, 0, 100);
        // Fund this test contract with Neuron tokens (neuron is deployed internally? No, need to deploy Neuron manually? Actually C uses Neuron contract via instantiateNeuronContract, but for simplicity we skip neuron interaction and directly set up state via mint? The bug is about balanceOf always returning 0, so we need a scenario where balanceOf matters.
        // Simpler: adjust admin access for an address, then use that address to call burn, which internally checks balances via _burn -> balanceOf. Since balanceOf returns 0 for buggy, the burn will see balance 0 and revert (insufficient balance), while reference sees actual balance and burns successfully.
        // First, give some tokens to a user by minting via internal _mint? But _mint is internal, can't call directly. We'll use the only public mint function, but it mints to msg.sender with price check. Alternative: directly adjust state via storage? Not allowed. Better: use the fact that after creating a game item, the admin (this test contract) can call mint with tokenId 0 and quantity 1. But mint requires Neuron approval. To avoid neuron complexity, we can use a different entry: setAllowedBurningAddresses lets an admin allow a burning address. Then that burning address can burn tokens from any account. The bug in balanceOf matters when burning because _burn calls balanceOf to check balance.
        // So we need an account that has tokens. We'll make this test contract (admin) own some tokens by using the mint function with price 0 and dailyAllowance > 0. The mint function requires that allowanceRemaining is updated and check dailyAllowanceReplenishTime. Let's make it simple: warping time to ensure daily allowance replenishes.
        // Step: warp to block.timestamp + 1 day so daily allowance is fresh.
        vm.warp(block.timestamp + 1 days);
        // Now the admin (this) calls mint with tokenId 0, quantity 1. Since itemPrice is 0, no NRN needed. dailyAllowance is 100, so allowanceRemaining will be 100 after replenish. The mint should succeed and give 1 token to admin.
        c.mint(0, 1);
        // Now admin has 1 token of id 0. Set allowed burning address to some other account (say address(0x1234)).
        address burner = address(0x1234);
        c.setAllowedBurningAddresses(burner);
        // Now burner tries to burn 1 token from admin. In reference, balanceOf(admin,0) returns 1, so burn succeeds. In buggy, balanceOf returns 0, so burn should revert because _burn checks fromBalance >= amount (0 >= 1 false).
        // Use try-catch to capture revert.
        bool ok = false;
        vm.prank(burner);
        try c.burn(address(this), 0, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok); // Reference: succeeds (ok true), Buggy: reverts (ok false)
    }
}

