// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a Neuron contract to use for payment, and instantiate in C
        vm.startPrank(address(this));
        Neuron neuron = new Neuron(address(this), address(this), address(0));
        c.instantiateNeuronContract(address(neuron));
        vm.stopPrank();

        // Create a game item with price 0 so minting requires no NRN
        vm.prank(address(this));
        c.createGameItem("item", "uri", false, true, 100, 0, 1);

        // Mint 1 token of id 0 to address(0x1)
        vm.prank(address(0x1));
        c.mint(0, 1);

        // Assert: balanceOf(address(0x1), 0) should be 1 in reference, 0 in buggy
        assertTrue(c.balanceOf(address(0x1), 0) == 1);
    }
}

