pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // create a game item with dailyAllowance=10, price=1, finiteSupply=true, itemsRemaining=100
        // Need a Neuron contract instance to call mint. Deploy one and set it
        address nrn = address(new Neuron(address(this), address(this), address(0x1234)));
        c.instantiateNeuronContract(nrn);

        // create a game item (tokenId 0)
        c.createGameItem("sword", "ipfs://test", true, true, 100, 1, 10);

        // fund address(1) with NRN
        vm.startPrank(address(1));
        // Mint some NRN to address(1) directly via Neuron.mint (we are admin)
        // But we need minter role. Let's first give address(1) the minter role
        // Actually simpler: call Neuron.mint directly from this test as owner
        vm.stopPrank();
        vm.prank(address(this));
        Neuron(nrn).mint(address(1), 100);

        // Now address(1) calls mint on C
        vm.startPrank(address(1));
        c.mint(0, 8);
        vm.stopPrank();

        // Reference: balanceOf(address(1), 0) should be 8
        // Bug: balanceOf reads _balances[0][address(1)] which is actually 8 because mint worked
        // Wait - the bug is in balanceOf returning _balances[id][address(1)] instead of [account]
        // For account = address(1), they are the same! Let's use a different account
        // Let address(2) check balanceOf(address(1), 0) - the bug returns wrong account's balance

        // Actually the bug: balanceOf(address(2), 0) returns _balances[0][address(1)] = 8 in bug
        // But reference returns 0 (address(2) has no tokens)

        uint256 refBalance = c.balanceOf(address(2), 0); // should be 0
        // Bug would return 8 (since _balances[0][address(1)] is 8, and bug always returns address(1)'s balance)
        assertTrue(refBalance == 0, "Balance should be 0 for address(2)");
    }
}

